"""Volume 2 · Module 11 « Métiers et stages » (A2)."""
import sys
sys.path.insert(0, '/home/claude/syllabus')
from lib.base import *
from lib.art import *
from lib.module import *
from lib.v2 import CP, CPCOL
from lib.render import to_pdf

MC = "#34495E"
TINT = "#EBEEF2"
MET = [("🧑‍⚕️", "infirmier · infirmière"), ("🧑‍🍳", "cuisinier · cuisinière"), ("💇", "coiffeur · coiffeuse"), ("🔧", "mécanicien · mécanicienne"), ("💡", "électricien · électricienne"), ("🥖", "boulanger · boulangère"),
       ("🛒", "vendeur · vendeuse"), ("🍽️", "serveur · serveuse"), ("👮", "policier · policière"), ("🧑‍🏫", "professeur · professeure"), ("⚖️", "avocat · avocate"), ("🚚", "chauffeur · chauffeuse"),
       ("🧑‍🌾", "agriculteur · agricultrice"), ("🩺", "un médecin · une médecin"), ("🧱", "maçon · maçonne"), ("💻", "informaticien · informaticienne")]
QUAL = [("⏰", "ponctuel(le)", "il / elle arrive à l'heure"), ("🧘", "patient(e)", "il / elle reste calme, attend sans s'énerver"), ("🗂️", "organisé(e)", "il / elle range, prévoit, fait une liste"), ("🤝", "sociable", "il / elle aime parler avec les gens"),
        ("🔍", "minutieux · minutieuse", "il / elle fait attention aux petits détails"), ("🎨", "créatif · créative", "il / elle a des idées nouvelles"), ("💪", "résistant(e)", "il / elle supporte la fatigue, le travail physique"), ("🙋", "motivé(e)", "il / elle a envie de travailler et d'apprendre")]


def build_v2m11(start=1, tstart=1, render=True):
    b = Book("V2 · M11", "Volume 2 · Je me débrouille · Module 11 · Métiers et stages", MC, start=start)
    E = Ex(b)
    vis = ('<div class="flex" style="justify-content:space-around;align-items:flex-end">' + avatar("mateo", 80, "sourire") + '<div style="font-size:34pt">🔧🚗</div>' + avatar("amina", 80, "rire") + '<div style="font-size:34pt">🩺💉</div>'
           + avatar("yonas", 80, "pense") + '<div style="font-size:34pt">🧑‍🍳📄</div>' + avatar("educ", 80, "sourire") + '</div>')
    opening(b, MC, 11, "Métiers et stages", vis, [("👷", "parler d'un métier : les tâches, le lieu, les qualités"), ("🙏", "demander poliment avec le conditionnel : je voudrais, pourriez-vous…"), ("❓", "poser des questions formelles"),
            ("📄", "lire une offre de stage et écrire mon CV"), ("🗂️", "comprendre une fiche métier"), ("🤝", "passer un entretien simulé")],
            ["Quel métier font tes parents ou des personnes de ta famille ?", "Quel métier voudrais-tu faire plus tard ? Pourquoi ?", "Quelles sont tes qualités ?"],
            ["un métier", "un stage", "une entreprise", "une qualité", "un CV", "un entretien", "je voudrais", "pourriez-vous", "ponctuel", "motivé"], TINT)

    # ---------- Découvrir ----------
    bd = '<div class="grid2" style="gap:3mm">' + "".join([
        bd_case(1, lr("prof", ["Bonne nouvelle ! Au printemps, chaque élève fera un stage d'observation d'un jour dans une entreprise."], "mateo", ["Génial ! Moi, je voudrais aller dans un garage !"], "sourire", "rire")),
        bd_case(2, lr("amina", ["Et moi, j'aimerais observer une infirmière à l'hôpital. J'aime aider les gens."], "yonas", ["Moi, je ne sais pas… J'adore cuisiner, mais je suis timide."], "rire", "pense")),
        bd_case(3, lr("prof", ["Pour trouver un stage, il faut d'abord écrire un CV et téléphoner poliment à l'entreprise."], "bilal", ["Un CV ? Mais je n'ai jamais travaillé !"], "neutre", "surpris")),
        bd_case(4, lr("educ", ["Ce n'est pas grave, Bilal. Dans ton CV, tu écris ta formation, tes langues et tes qualités. Tu parles quatre langues, c'est une force !"], "bilal", ["Ah oui ? Je n'y avais pas pensé !"], "sourire", "sourire")),
        bd_case(5, lr("educ", ["Allez, on s'entraîne. Yonas, je suis le patron du restaurant. Bonjour, que puis-je faire pour vous ?"], "yonas", ["Euh… Bonjour Monsieur. Je voudrais faire un stage dans votre cuisine, s'il vous plaît."], "neutre", "pense")),
        bd_case(6, lr("educ", ["Très bien ! Et pourquoi notre restaurant ?"], "yonas", ["Parce que je suis motivé et ponctuel, et j'adore la cuisine du monde. Pourriez-vous m'accueillir un jour ?"], "sourire", "sourire")),
    ]) + '</div>'
    e = E("J'écoute et je lis la BD : un stage d'un jour.", bd, ["ecoute", "lis"], 1, "A",
          script="Lire deux fois, en jouant l'enthousiasme de Mateo, la timidité de Yonas, puis son assurance à la fin. Demander : « Qu'est-ce que Mme Lambert annonce ? Où Mateo et Amina voudraient-ils aller ? Pourquoi Bilal est-il inquiet ? Que conseille M. Diallo ? Comment Yonas demande-t-il le stage ? »", sol="Activité orale.")
    b.page(f'<h2>Découvrir · Un stage d\'un jour</h2>{e}', "Découvrir")
    e = E("Je réponds par une phrase complète.", f'<p>1. Qu\'est-ce que chaque élève va faire au printemps ? {blank("xl")}</p><p>2. Où Mateo voudrait-il faire son stage ? Et Amina ? Pourquoi ? {blank("xl")}</p><p>3. Quel est le problème de Yonas ? {blank("xl")}</p><p>4. Que faut-il faire pour trouver un stage ? (2 choses) {blank("xl")}</p><p>5. Qu\'est-ce que Bilal peut écrire dans son CV ? {blank("xl")}</p><p>6. Quelles qualités Yonas donne-t-il au patron ? {blank("xl")}</p>', ["lis", "ecris"], 1, "B",
          sol="1. Un stage d'observation d'un jour dans une entreprise. — 2. Mateo : dans un garage ; Amina : à l'hôpital, avec une infirmière, parce qu'elle aime aider les gens. — 3. Il ne sait pas quel stage choisir : il adore cuisiner, mais il est timide. — 4. Écrire un CV et téléphoner poliment à l'entreprise. — 5. Sa formation, ses langues (il parle quatre langues) et ses qualités. — 6. Il est motivé et ponctuel (et il adore la cuisine du monde).")
    e2 = E("Vrai ou faux ? Je coche.", vf(["Le stage dure une semaine.", "Bilal a déjà travaillé dans un restaurant.", "Pour M. Diallo, parler quatre langues est une force.", "À la fin, Yonas utilise le conditionnel pour demander poliment."]), ["lis", "coche"], 1, "B",
           sol="Faux (un jour) · Faux (il n'a jamais travaillé) · Vrai · Vrai (« Pourriez-vous m'accueillir… »)")
    e3 = E("Et toi ? Où aimerais-tu faire un stage d'un jour ? Pourquoi ? (2 phrases)", lines(2), ["ecris"], 2, "C", sol="Ex. : J'aimerais faire un stage dans une pharmacie, parce que je voudrais devenir pharmacienne.")
    e4 = E("Les mots de la BD. Je trouve le mot qui veut dire…", '<p>1. une période pour découvrir un métier dans une entreprise : un ______________ 2. le chef d\'une entreprise : le ______________ 3. un document qui présente ma formation et mes qualités : un ______________ 4. qui a très envie : ______________ 5. qui arrive toujours à l\'heure : ______________</p>', ["lis", "ecris"], 1, "B", sol="1. stage — 2. patron (le directeur, la directrice) — 3. CV — 4. motivé — 5. ponctuel")
    b.page(f'{e}{e2}{e3}{e4}', "Découvrir")
    fly = f'''<div class="doc" style="transform:none;border:2px solid {MC};background:#fff;padding:3mm 4mm"><div class="flex" style="justify-content:space-between"><div><b style="font-size:14pt;color:{MC}">🎪 Salon des métiers · Athénée des Trois Ponts</b><br><span class="xs muted">(école fictive) · jeudi 18 mars · de 9 h à 15 h · salle de gymnastique · entrée gratuite</span></div><div style="font-size:26pt">👷‍♀️</div></div>
{table(["Heure", "Stand ou atelier", "Qui ?"], [["9 h – 15 h", "15 stands de métiers : soins, cuisine, bâtiment, mécanique, commerce, informatique, coiffure…", "des professionnels de la région"], ["10 h", "Atelier « Réussir son CV » (salle 12)", "M. Diallo, éducateur"], ["11 h", "Témoignage : « De la classe DASPA à mon métier d'électricienne »", "Sarah, ancienne élève (25 ans)"], ["13 h", "Entretiens simulés (inscription au stand d'accueil)", "des bénévoles d'entreprises"], ["14 h", "Présentation des options de l'enseignement qualifiant", "le centre PMS"]], ["24mm", "100mm", "58mm"])}
<p class="xs" style="margin:1mm 0 0">📌 Apportez un stylo et votre CV si vous l'avez déjà. · 🎟️ Les élèves de 1<sup>re</sup> et 2<sup>e</sup> visitent le salon avec leur titulaire. · Renseignements : secrétariat, 081 00 00 00 (numéro fictif).</p></div>'''
    e = E("Je lis le programme du salon des métiers. Je réponds.", fly + f'<p class="mt2">1. Quand et où a lieu le salon ? {blank("xl")}</p><p>2. Combien coûte l\'entrée ? {blank("s")} 3. Qui est Sarah ? De quoi va-t-elle parler ? {blank("xl")}</p><p>4. Yonas veut s\'entraîner pour un entretien. À quelle heure ? Que doit-il faire avant ? {blank("xl")}</p><p>5. Quel atelier t\'intéresse le plus ? Pourquoi ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. Le jeudi 18 mars, de 9 h à 15 h, dans la salle de gymnastique de l'Athénée des Trois Ponts. — 2. C'est gratuit. — 3. Une ancienne élève de 25 ans ; elle va parler de son parcours, de la classe DASPA à son métier d'électricienne. — 4. À 13 h ; il doit s'inscrire au stand d'accueil. — 5. Réponse personnelle.")
    b.page(f'<span class="tag-doc">📄 DOCUMENT DE LA VIE</span><h2>Découvrir · Le salon des métiers</h2>{e}', "Découvrir")

    # ---------- Lexique ----------
    e = E("Les métiers. J'écoute et je répète (masculin · féminin).", '<div class="grid4">' + "".join(f'<div class="card c" style="padding:2mm"><span class="emo s">{em}</span><b class="sm">{t}</b></div>' for em, t in MET) + '</div>', ["ecoute", "repete"], 1, "A",
          script="Lire chaque métier au masculin puis au féminin. Faire remarquer les terminaisons (-ier / -ière, -eur / -euse, -ien / -ienne, -teur / -trice). En Belgique, la féminisation des noms de métiers est officielle depuis 1993 (une professeure, une maçonne, une chauffeuse).", sol="Activité orale.")
    e2 = E("Où travaillent-ils ? Je relie le métier et le lieu.", relie(["l'infirmière", "le mécanicien", "la vendeuse", "le cuisinier", "l'agricultrice", "le boulanger"], ["dans un magasin", "à la ferme, dans les champs", "dans un garage", "à l'hôpital", "dans une boulangerie", "dans un restaurant"]), ["relie"], 1, "B",
           sol="infirmière → hôpital · mécanicien → garage · vendeuse → magasin · cuisinier → restaurant · agricultrice → ferme · boulanger → boulangerie")
    b.page(f'<h2>Les métiers et les lieux de travail</h2>{e}{e2}', "Lexique")
    l0 = lecon("Le masculin et le féminin des métiers", table(["Masculin", "Féminin", "Exemples"], [["-ier", "-ière", "infirmier → infirm<b>ière</b> · cuisinier → cuisin<b>ière</b>"], ["-eur", "-euse", "coiffeur → coiff<b>euse</b> · vendeur → vend<b>euse</b>"], ["-teur", "-trice", "agriculteur → agricul<b>trice</b> · animateur → anima<b>trice</b>"], ["-ien", "-ienne", "mécanicien → mécanic<b>ienne</b> · électricien → électric<b>ienne</b>"], ["-er", "-ère", "boulanger → boulang<b>ère</b> · policier → polic<b>ière</b>"], ["+ e", "", "avocat → avocat<b>e</b> · employé → employé<b>e</b> · professeur → professeur<b>e</b>"], ["même mot", "", "un / une <b>médecin</b>, <b>pilote</b>, <b>architecte</b>, <b>secrétaire</b>, <b>journaliste</b>"]], ["32mm", "32mm", "118mm"]) +
                '<p class="sm mt2" style="margin-bottom:0">💬 Pour dire son métier : <b>Je suis</b> infirmière. (sans article !) · <b>Elle est</b> mécanicienne. · <b>C\'est une</b> bonne mécanicienne. (avec un adjectif → c\'est un / une) · <b>Je voudrais devenir</b> électricien.</p>')
    e = E("J'écris le féminin.", '<p>1. un serveur → une ______________ 2. un informaticien → une ______________ 3. un agriculteur → une ______________ 4. un pâtissier → une ______________ 5. un dentiste → une ______________ 6. un chanteur → une ______________</p>', ["ecris"], 1, "C",
          sol="1. serveuse — 2. informaticienne — 3. agricultrice — 4. pâtissière — 5. dentiste — 6. chanteuse")
    e2 = E("Sans article ou avec article ? Je complète avec Ø, un ou une.", '<div class="card" style="line-height:1.9">1. Ma mère est ______ aide-soignante. 2. C\'est ______ aide-soignante très gentille. 3. Mon oncle est ______ chauffeur de bus. 4. C\'est ______ excellent cuisinier. 5. Je voudrais devenir ______ policière.</div>', ["complete"], 2, "C",
           sol="1. Ø — 2. une — 3. Ø — 4. un — 5. Ø")
    b.page(f'{l0}{e}{e2}', "Lexique")
    e = E("Les qualités. Je lis et je donne un métier où cette qualité est importante.", table(["", "La qualité", "Ça veut dire…", "Un métier"], [[f'<span style="font-size:14pt">{a}</span>', f'<b>{w}</b>', d, ""] for a, w, d in QUAL], ["11mm", "44mm", "84mm", "43mm"]), ["lis", "ecris"], 1, "C",
          sol="Ex. : ponctuel → chauffeur de bus · patient → professeur, infirmier · organisé → secrétaire · sociable → vendeur · minutieux → électricien, pâtissier · créatif → coiffeur, graphiste · résistant → maçon, agriculteur · motivé → tous les métiers !")
    e2 = E("Qui a quelle qualité ? Je lis et j'écris l'adjectif.", '<p>1. Daria range toujours son bureau et prépare son sac la veille. Elle est ______________ .</p><p>2. Bilal parle à tout le monde à la récré. Il est ______________ .</p><p>3. Fatou explique dix fois la même chose à sa petite sœur sans s\'énerver. Elle est ______________ .</p><p>4. Mateo invente de nouvelles recettes de crêpes. Il est ______________ .</p>', ["lis", "ecris"], 1, "C",
           sol="1. organisée — 2. sociable — 3. patiente — 4. créatif")
    e3 = E("Mes qualités. J'écris 3 qualités et un exemple pour chacune (Je suis… parce que… / par exemple…).", lines(3), ["ecris"], 2, "C", sol="Ex. : Je suis ponctuelle : j'arrive toujours à l'heure à l'école. Je suis sociable, par exemple j'aide les nouveaux élèves.")
    b.page(f'<h2>Les qualités</h2>{e}{e2}{e3}', "Lexique")
    bel = table(["En Belgique, on dit…", "En France, on dit…", "Exemple"], [["le <b>Forem</b>", "France Travail (l'agence pour l'emploi)", "Ma sœur est inscrite au Forem."], ["un <b>jobiste</b>, un job étudiant", "un étudiant qui travaille", "Cet été, je suis jobiste au supermarché."], ["le <b>pécule</b> de vacances", "la prime de vacances", "Mon père reçoit son pécule en mai."], ["le <b>préfet</b> (dans un athénée)", "le proviseur", "Le préfet a signé ma convention de stage."]], ["50mm", "58mm", "74mm"])
    e = E("🇧🇪 Les mots d'ici. Je lis et je réécris la phrase en français de France.", bel + '<p class="mt2">Le préfet a dit que ma sœur, inscrite au Forem, pouvait être jobiste à l\'école. → ______________________________________________________</p>', ["lis", "ecris"], 2, "B",
          sol="Le proviseur a dit que ma sœur, inscrite à France Travail, pouvait travailler comme étudiante à l'école.")
    e2 = E("Les verbes du travail. Je complète avec : travaille · s'occupe · répare · soigne · sert · vend.", '<div class="card" style="line-height:1.9">1. Le mécanicien ______________ les voitures. 2. L\'infirmière ______________ les malades. 3. La serveuse ______________ les clients. 4. Le vendeur ______________ des vêtements. 5. L\'aide-soignant ______________ des personnes âgées. 6. Mon père ______________ de nuit.</div>', ["complete"], 1, "C",
           sol="1. répare — 2. soigne — 3. sert — 4. vend — 5. s'occupe — 6. travaille")
    e3 = E("J'écoute 4 personnes qui parlent de leur métier. Je complète le tableau.", table(["", "Métier", "Lieu", "Une qualité"], [[n, "", "", ""] for n in ["Karim", "Mme Lejeune", "Lucas", "Aïcha"]], ["30mm", "50mm", "50mm", "52mm"]).replace("<td></td>", '<td style="height:7.5mm"></td>'), ["ecoute", "ecris"], 2, "A",
           script="« Karim : Je suis boulanger. Je commence à quatre heures du matin dans ma boulangerie, donc il faut être résistant ! — Mme Lejeune : Je suis aide-soignante dans une maison de repos. Je m'occupe des personnes âgées : il faut être très patiente. — Lucas : Moi, je suis électricien. Je travaille dans des maisons et des bureaux. Je dois être minutieux, sinon c'est dangereux ! — Aïcha : Je suis coiffeuse dans un salon à Charleroi. J'adore créer de nouvelles coupes : il faut être créative et sociable. »",
           sol="Karim : boulanger · boulangerie · résistant — Mme Lejeune : aide-soignante · maison de repos · patiente — Lucas : électricien · maisons et bureaux · minutieux — Aïcha : coiffeuse · salon de coiffure (Charleroi) · créative, sociable")
    b.page(f'<h2>Les mots d\'ici · les verbes du travail</h2>{e}{e2}{e3}', "Lexique")

    # ---------- Leçon 1 : conditionnel de politesse ----------
    l1 = lecon("Le conditionnel de politesse", '''<p>Pour demander <b>poliment</b>, j'utilise le <b>conditionnel présent</b> : <i>Je veux un stage.</i> 😐 → <i>Je <b>voudrais</b> un stage.</i> 🙂</p>
<div class="grid2"><div class="card" style="background:#fff"><b>La formation</b><p class="sm" style="margin:1mm 0 0">radical du <b>futur</b> + terminaisons de l'<b>imparfait</b><br>-ais · -ais · -ait · -ions · -iez · -aient<br>aimer → j'aimer<b>ais</b> · pouvoir → je pourr<b>ais</b><br>vouloir → je voudr<b>ais</b> · avoir → j'aur<b>ais</b><br>être → je ser<b>ais</b> · devoir → je devr<b>ais</b></p></div>
<div class="card" style="background:#fff"><b>Les phrases utiles</b><p class="sm" style="margin:1mm 0 0"><b>Je voudrais</b> faire un stage chez vous.<br><b>J'aimerais</b> savoir si c'est possible.<br><b>Pourriez-vous</b> m'envoyer l'adresse ?<br><b>Auriez-vous</b> un moment pour me parler ?<br><b>Serait-il possible</b> de venir lundi ?</p></div></div>''' +
                table(["", "vouloir", "pouvoir", "aimer"], [["je", "voudrais", "pourrais", "aimerais"], ["tu", "voudrais", "pourrais", "aimerais"], ["il / elle / on", "voudrait", "pourrait", "aimerait"], ["nous", "voudrions", "pourrions", "aimerions"], ["vous", "voudriez", "pourriez", "aimeriez"], ["ils / elles", "voudraient", "pourraient", "aimeraient"]], ["40mm", "47mm", "47mm", "48mm"]))
    e = E("Je rends les phrases plus polies avec le conditionnel.", '<p>1. Je veux parler au directeur. → ______________________________</p><p>2. Vous pouvez répéter ? → ______________________________</p><p>3. J\'aime visiter l\'atelier. → ______________________________</p><p>4. Vous avez cinq minutes ? → ______________________________</p>', ["ecris"], 1, "C",
          sol="1. Je voudrais parler au directeur. — 2. Pourriez-vous répéter, s'il vous plaît ? — 3. J'aimerais visiter l'atelier. — 4. Auriez-vous cinq minutes ?")
    b.page(f'{l1}{e}', "Leçon 1")
    e = E("Je conjugue au conditionnel présent.", '<p>1. Nous (vouloir) ______________ visiter l\'entreprise. 2. (Pouvoir) ______________ -vous m\'aider ? 3. Mes parents (aimer) ______________ vous rencontrer. 4. Tu (avoir) ______________ un stylo ? 5. Il (être) ______________ content de venir. 6. Elles (pouvoir) ______________ commencer à 8 h.</p>', ["complete"], 1, "C",
          sol="1. voudrions — 2. Pourriez — 3. aimeraient — 4. aurais — 5. serait — 6. pourraient")
    e2 = E("Poli 🙂 ou pas poli 😐 ? Je coche.", vf(["Donne-moi un stage !", "Je voudrais un renseignement, s'il vous plaît.", "Pourriez-vous me rappeler demain ?", "Je veux parler au chef. Tout de suite."]).replace("Vrai", "🙂").replace("Faux", "😐"), ["lis", "coche"], 1, "B",
           sol="😐 · 🙂 · 🙂 · 😐")
    e3 = E("J'écoute Amina qui téléphone à l'hôpital. Je complète ses phrases.", '<div class="card" style="line-height:1.9">1. Bonjour Madame, je m\'appelle Amina. Je ______________ faire un stage d\'observation d\'un jour.<br>2. J\'______________ observer le travail d\'une infirmière.<br>3. ______________ -vous me dire à qui envoyer mon CV ?<br>4. ______________ -il possible de venir le mardi 23 avril ?</div>', ["ecoute", "complete"], 2, "A",
           script="« — Hôpital Sainte-Claire, bonjour. (hôpital fictif) — Bonjour Madame, je m'appelle Amina, je suis élève en classe DASPA. Je voudrais faire un stage d'observation d'un jour. J'aimerais observer le travail d'une infirmière. Pourriez-vous me dire à qui envoyer mon CV ? — Oui, envoyez-le au service des ressources humaines. — Merci. Serait-il possible de venir le mardi 23 avril ? — Je vais demander. On vous rappelle. »",
           sol="1. voudrais — 2. aimerais — 3. Pourriez — 4. Serait")
    e4 = E("Défi ! J'écris 4 demandes polies pour mon stage (différentes) : à un garage, à une crèche, à un magasin, à une mairie (administration communale).", lines(4), ["ecris"], 3, "C",
           sol="Ex. : Je voudrais observer le travail d'un mécanicien. Pourriez-vous m'accueillir un jour à la crèche ? Auriez-vous une place de stage dans votre magasin ? Serait-il possible de découvrir le service population de la commune ?")
    b.page(f'{e}{e2}{e3}{e4}', "S'entraîner")

    # ---------- Leçon 2 : questions formelles ----------
    l2 = lecon("Poser des questions formelles", table(["Registre", "Structure", "Exemple"], [["😎 familier (oral, entre amis)", "intonation ↗️", "Tu commences à quelle heure ?"], ["🙂 courant", "<b>est-ce que</b> + sujet + verbe", "<b>Est-ce que</b> vous commencez à 8 h ?"], ["🎩 formel (écrit, entretien)", "<b>inversion</b> : verbe-sujet", "<b>Commencez-vous</b> à 8 h ? · <b>À quelle heure commence</b> le travail ?"]], ["52mm", "56mm", "74mm"]) + '''
<div class="grid2 mt2"><div class="card" style="background:#fff"><b>L'inversion</b><p class="sm" style="margin:1mm 0 0">Vous travaillez le samedi. → <b>Travaillez-vous</b> le samedi ?<br>avec un trait d'union : <b>Pouvez-vous</b>… ? <b>Avez-vous</b>… ?<br>il / elle + voyelle → <b>-t-</b> : <b>A-t-il</b> un CV ? <b>Travaille-t-elle</b> ici ?</p></div>
<div class="card" style="background:#fff"><b>Les mots interrogatifs</b><p class="sm" style="margin:1mm 0 0"><b>Quel(le)s</b> sont les horaires ? · <b>Où</b> se trouve l'atelier ?<br><b>Combien de</b> personnes travaillent ici ?<br><b>Comment</b> dois-je m'habiller ? · <b>Pourquoi</b> avez-vous choisi ce métier ?<br><b>Que</b> faites-vous le matin ? (= Qu'est-ce que vous faites ?)</p></div></div>''')
    e = E("Je transforme les questions en questions formelles (inversion).", '<p>1. Vous avez un uniforme ? → ______________________________</p><p>2. Est-ce que vous travaillez le week-end ? → ______________________________</p><p>3. Tu peux m\'expliquer ? (vous) → ______________________________</p><p>4. Est-ce qu\'il a besoin d\'un stagiaire ? → ______________________________</p>', ["ecris"], 1, "C",
          sol="1. Avez-vous un uniforme ? — 2. Travaillez-vous le week-end ? — 3. Pouvez-vous m'expliquer ? — 4. A-t-il besoin d'un stagiaire ?")
    b.page(f'{l2}{e}', "Leçon 2")
    e = E("Je trouve la question. J'utilise le mot interrogatif entre parenthèses et l'inversion.", '<p>1. (quelle heure) ______________________________ ? — Le travail commence à 7 h 30.</p><p>2. (combien) ______________________________ ? — Nous sommes douze dans l\'équipe.</p><p>3. (où) ______________________________ ? — Le vestiaire se trouve au fond du couloir.</p><p>4. (pourquoi) ______________________________ ? — Parce que j\'aime le contact avec les clients.</p>', ["ecris"], 2, "C",
          sol="1. À quelle heure commence le travail ? — 2. Combien de personnes êtes-vous dans l'équipe ? — 3. Où se trouve le vestiaire ? — 4. Pourquoi avez-vous choisi ce métier ? (ou : Pourquoi voulez-vous travailler ici ?)")
    e2 = E("Familier (F), courant (C) ou formel (FO) ? J'écris.", '<div class="grid2" style="gap:1mm 6mm"><p>___ Tu bosses où ?</p><p>___ Où travaillez-vous ?</p><p>___ Est-ce que je peux venir ?</p><p>___ Puis-je vous poser une question ?</p><p>___ C\'est combien, le salaire ?</p><p>___ Quel est le salaire ?</p></div>', ["lis", "ecris"], 1, "B",
           sol="F (« bosser » = familier) · FO · C · FO · F · FO (ou C)")
    e3 = E("Le questionnaire du stagiaire. J'écris 5 questions formelles que je peux poser pendant mon stage (horaires, tâches, tenue, formation, qualités).", lines(5), ["ecris"], 2, "C",
           sol="Ex. : Quels sont les horaires ? Que faites-vous pendant une journée ? Comment dois-je m'habiller ? Quelle formation avez-vous suivie ? Quelles qualités faut-il pour ce métier ?")
    e4 = E("En duo : interview d'un adulte de l'école (secrétaire, éducateur, cuisinier…). On prépare 4 questions formelles, on fait l'interview et on note les réponses.", lines(3), ["parle", "duo", "ecris"], 2, "A",
           sol="Questions formelles correctes ; prise de notes.")
    b.page(f'{e}{e2}{e3}{e4}', "S'entraîner")

    # ---------- Leçon 3 : parler d'un métier ----------
    l3 = lecon("Présenter un métier", '''<p>Pour présenter un métier, je réponds à ces questions :</p>''' + table(["Question", "Expressions utiles", "Exemple : l'aide-soignant(e)"], [
        ["Quoi ?", "il / elle s'occupe de… · il / elle est chargé(e) de… · son travail consiste à + infinitif", "Il s'occupe des malades : il les aide à se laver, à manger."],
        ["Où ?", "il / elle travaille dans un / une… · à l'… · chez…", "Il travaille à l'hôpital ou dans une maison de repos."],
        ["Quand ?", "le jour, la nuit, le week-end · à temps plein / à temps partiel · en équipe", "Il travaille parfois la nuit et le week-end."],
        ["Comment ?", "il faut être + qualité · il faut savoir + infinitif · il utilise…", "Il faut être patient et doux. Il faut savoir écouter."],
        ["Pour devenir… ?", "il faut faire des études de… · une formation de… · un diplôme de…", "Il faut suivre une formation d'aide-soignant (enseignement qualifiant ou promotion sociale)."]], ["24mm", "78mm", "80mm"]) +
                '<div class="astuce" style="margin:2mm 0 0">Pour dire ce que j\'aime : <b>Ce qui me plaît</b> dans ce métier, c\'est… · <b>Ce que j\'aime</b>, c\'est… · <b>Je voudrais devenir</b>… <b>parce que</b>…</div>')
    e = E("Je complète la présentation du métier de cuisinier avec : s'occupe · travaille · il faut · consiste · formation.", '<div class="card big" style="line-height:1.9">Le cuisinier ______________ dans un restaurant, une cantine ou un hôtel. Son travail ______________ à préparer les plats. Il ______________ aussi des commandes et du nettoyage. ______________ être rapide, organisé et résistant. Pour devenir cuisinier, on peut suivre une ______________ dans l\'enseignement qualifiant (hôtellerie).</div>', ["complete"], 1, "C",
          sol="travaille · consiste · s'occupe · Il faut · formation")
    b.page(f'{l3}{e}', "Leçon 3")
    e = E("Devinettes. Je lis et j'écris le métier.", '<p>1. Il travaille la nuit, il fait du pain et des croissants. → ______________</p><p>2. Elle travaille dans un tribunal. Elle défend les personnes. → ______________</p><p>3. Il conduit un bus. Il faut être ponctuel et prudent. → ______________</p><p>4. Elle répare les ordinateurs et crée des programmes. → ______________</p><p>5. Il construit des murs avec des briques. → ______________</p>', ["lis", "ecris"], 1, "B",
          sol="1. boulanger — 2. avocate — 3. chauffeur de bus — 4. informaticienne — 5. maçon")
    e2 = E("Je présente le métier de mon choix (5 phrases) : quoi ? où ? quand ? comment ? pour devenir ?", lines(5), ["ecris"], 2, "C",
           sol="Présentation complète avec les expressions de la leçon.")
    e3 = E("J'écoute Sarah, ancienne élève de DASPA, qui parle de son métier d'électricienne. Je réponds.", f'<p>1. Depuis quand est-elle en Belgique ? {blank("l")} 2. Quelle formation a-t-elle suivie ? {blank("l")}</p><p>3. Où travaille-t-elle ? {blank("xl")}</p><p>4. Qu\'est-ce qui lui plaît dans son métier ? {blank("xl")}</p><p>5. Quel conseil donne-t-elle aux élèves ? {blank("xl")}</p>', ["ecoute", "ecris"], 2, "A",
           script="« Bonjour ! Je m'appelle Sarah, j'ai vingt-cinq ans. Je suis arrivée en Belgique il y a dix ans, sans parler français. J'ai passé un an en classe DASPA, comme vous. Ensuite, j'ai choisi l'option électricité dans l'enseignement qualifiant. Aujourd'hui, je travaille pour une petite entreprise : on installe l'électricité dans des maisons neuves. Ce qui me plaît, c'est que chaque jour est différent, et je suis fière quand la lumière s'allume ! Mon conseil : n'ayez pas peur de choisir un métier où il y a peu de filles ou peu de garçons. Et faites des stages : c'est comme ça qu'on découvre ce qu'on aime ! » (témoignage fictif)",
           sol="1. Depuis dix ans. — 2. Un an de DASPA, puis l'option électricité dans l'enseignement qualifiant. — 3. Dans une petite entreprise : elle installe l'électricité dans des maisons neuves. — 4. Chaque jour est différent ; elle est fière quand la lumière s'allume. — 5. Ne pas avoir peur de choisir un métier où il y a peu de filles ou de garçons ; faire des stages.")
    b.page(f'{e}{e2}{e3}', "S'entraîner")

    # ---------- Leçon 4 : le CV ----------
    cv = f'''<div class="doc" style="transform:none;border:1.5px solid #9aa1b1;background:#fff;padding:0;font-size:9.6pt;line-height:1.4;display:grid;grid-template-columns:56mm 1fr">
<div style="background:{MC};color:#fff;padding:3mm"><div style="width:22mm;height:22mm;border-radius:50%;background:#C9D3DD;margin:0 auto 2mm;display:flex;align-items:center;justify-content:center;font-size:20pt">🙂</div><b style="font-size:12pt">Yonas TESFAYE</b><br><span class="xs">(élève fictif)</span><p class="xs" style="margin:2mm 0 0"><b>①</b> 📍 rue des Tilleuls 14, 5000 Namur<br>📞 0470 00 00 00<br>✉️ yonas.tesfaye@ecole-exemple.be<br>🎂 14 ans</p>
<p class="xs" style="margin:2mm 0 0"><b>② Langues</b><br>tigrinya : langue maternelle<br>amharique : très bien<br>anglais : bien<br>français : en apprentissage (A2)</p><p class="xs" style="margin:2mm 0 0"><b>③ Qualités</b><br>motivé · ponctuel · calme · curieux</p></div>
<div style="padding:3mm"><b style="color:{MC};font-size:11pt">④ Objectif</b><p style="margin:.5mm 0 2mm">Découvrir le métier de cuisinier pendant un stage d'observation d'un jour.</p>
<b style="color:{MC};font-size:11pt">⑤ Formation</b><p style="margin:.5mm 0 2mm">depuis septembre 2026 : classe DASPA, Athénée des Trois Ponts, Namur<br>2019-2024 : école primaire, Asmara (Érythrée)</p>
<b style="color:{MC};font-size:11pt">⑥ Expériences</b><p style="margin:.5mm 0 2mm">• aide en cuisine pendant les fêtes de ma communauté (repas pour 100 personnes)<br>• bénévole à la journée « Cour propre » de l'école (2026)</p>
<b style="color:{MC};font-size:11pt">⑦ Compétences</b><p style="margin:.5mm 0 2mm">préparer des plats simples · travailler en équipe · utiliser un ordinateur (traitement de texte)</p>
<b style="color:{MC};font-size:11pt">⑧ Centres d'intérêt</b><p style="margin:.5mm 0 0">la cuisine du monde · le football (club de Jambes) · le dessin</p></div></div>'''
    l4 = lecon("Le CV (curriculum vitae)", '''<div class="grid2"><div class="card" style="background:#fff"><b>Les parties du CV</b><p class="sm" style="margin:1mm 0 0">① les coordonnées · ② les langues · ③ les qualités · ④ l'objectif · ⑤ la formation (études) · ⑥ les expériences · ⑦ les compétences · ⑧ les centres d'intérêt (loisirs)</p></div>
<div class="card" style="background:#fff"><b>✍️ Comment écrire ?</b><p class="sm" style="margin:1mm 0 0">• <b>une page</b>, clair, sans faute<br>• des phrases <b>courtes</b> ou des mots-clés, sans « je »<br>• les dates du plus <b>récent</b> au plus ancien<br>• une adresse électronique <b>sérieuse</b> (pas « bebou_du_93 »)<br>• toujours <b>vrai</b> : on ne ment pas dans un CV !</p></div></div>
<div class="astuce" style="margin:2mm 0 0">Je n'ai jamais travaillé ? J'écris mes <b>expériences</b> : aider à la maison, garder des enfants, être bénévole, être délégué de classe, faire du sport en club… Mes <b>langues</b> sont une grande force !</div>''')
    e = E("J'observe le CV de Yonas et j'écris le numéro de la partie.", cv + '<div class="grid3 mt2" style="gap:1mm 4mm;font-size:10pt"><p>___ « bénévole à la journée Cour propre »</p><p>___ « le football »</p><p>___ « classe DASPA »</p><p>___ « anglais : bien »</p><p>___ « Découvrir le métier de cuisinier »</p><p>___ « travailler en équipe »</p></div>', ["lis", "numerote"], 1, "B",
          sol="⑥ · ⑧ · ⑤ · ② · ④ · ⑦")
    b.page(f'{l4}{e}', "Leçon 4")
    e = E("Expérience, compétence ou centre d'intérêt ? Je classe dans le tableau.", '<p class="sm">garder mon petit frère le mercredi · parler arabe et anglais · la musique · aider au magasin de mon oncle · réparer un vélo · le basket en club · utiliser un tableur · délégué(e) de classe</p>' + table(["⑥ Expériences", "⑦ Compétences", "⑧ Centres d'intérêt"], [["", "", ""]], ["61mm", "61mm", "60mm"]).replace("<td></td>", '<td style="height:24mm"></td>'), ["lis", "ecris"], 2, "C",
          sol="Expériences : garder mon petit frère, aider au magasin de mon oncle, délégué(e) de classe · Compétences : parler arabe et anglais (ou : langues), réparer un vélo, utiliser un tableur · Centres d'intérêt : la musique, le basket en club")
    e2 = E("Je corrige le CV de Mateo : je trouve 4 erreurs et j'explique.", '<div class="card sm" style="font-family:monospace;background:#fff">CV de Mateo · mateo_le_boss_du_foot@mail.com<br>Formation : 2018 école primaire à Bogotá · 2026 DASPA<br>Expériences : Je suis allé au garage de mon oncle. J\'ai adoré !!!<br>Langues : espagnol, anglais, français<br>Qualités : je suis le meilleur mécanicien du monde</div>' + lines(3), ["lis", "ecris"], 3, "C",
           sol="1. Adresse électronique pas sérieuse. 2. Dates pas dans le bon ordre (le plus récent d'abord : 2026 DASPA, puis 2018…). 3. Expériences : pas de « je », pas de « !!! », préciser : « aide au garage de mon oncle (observation, rangement des outils) ». 4. Qualités exagérées et fausses : écrire « motivé, minutieux ». (+ préciser le niveau de chaque langue)")
    e3 = E("Mes langues. J'écris toutes les langues que je parle et mon niveau (langue maternelle, très bien, bien, notions, en apprentissage).", table(["Langue", "Niveau"], [["", ""] for _ in range(4)], ["80mm", "102mm"]).replace("<td></td>", '<td style="height:7mm"></td>'), ["ecris"], 1, "C", sol="Tableau personnel.")
    e4 = E("Je transforme les phrases en mots-clés pour le CV (sans « je »).", '<p>1. J\'ai aidé mon oncle dans son magasin pendant l\'été. → ______________________________</p><p>2. Je sais utiliser un ordinateur. → ______________________________</p><p>3. Je joue au basket dans un club depuis deux ans. → ______________________________</p>', ["ecris"], 2, "C",
           sol="Ex. : 1. Aide au magasin de mon oncle (été 2026) — 2. Utilisation d'un ordinateur (traitement de texte) — 3. Basket en club (depuis 2024)")
    b.page(f'{e}{e2}{e3}{e4}', "S'entraîner")

    # ---------- FLSco : fiche métier ----------
    fiche = f'''<div class="doc" style="transform:none;border:2px solid {MC};background:#fff;padding:3mm 4mm;font-size:9.8pt;line-height:1.45"><div class="flex" style="justify-content:space-between"><b style="font-size:13pt;color:{MC}">🗂️ Fiche métier · Aide-soignant / Aide-soignante</b><span class="xs muted">(fiche simplifiée)</span></div>
<p style="margin:1.5mm 0 0"><b>① Description</b> L'aide-soignant(e) aide les personnes malades, âgées ou handicapées dans la vie de tous les jours. Il ou elle travaille sous la responsabilité d'un infirmier ou d'une infirmière.</p>
<p style="margin:1mm 0 0"><b>② Tâches</b> aider la personne à se laver, à s'habiller, à manger · faire le lit · mesurer la température · observer et signaler les changements à l'infirmier · parler avec la personne, la rassurer.</p>
<p style="margin:1mm 0 0"><b>③ Lieux de travail</b> hôpital · maison de repos · soins à domicile.</p>
<p style="margin:1mm 0 0"><b>④ Conditions de travail</b> travail en équipe · horaires variables (matin, soir, nuit, week-end) · beaucoup de temps debout · contact avec la maladie et parfois la mort.</p>
<p style="margin:1mm 0 0"><b>⑤ Qualités</b> patience · douceur · écoute · bonne résistance physique · discrétion (secret professionnel) · hygiène.</p>
<p style="margin:1mm 0 0"><b>⑥ Formation</b> En Belgique, on peut devenir aide-soignant(e) après une formation dans l'enseignement secondaire qualifiant (section « aide-soignant ») ou dans l'enseignement de promotion sociale (pour adultes). Il faut ensuite être enregistré auprès du SPF Santé publique pour exercer.</p>
<p style="margin:1mm 0 0"><b>⑦ Débouchés</b> C'est un métier très demandé (métier « en pénurie » dans de nombreuses régions). Avec des études en plus, on peut devenir infirmier ou infirmière.</p></div>'''
    l5 = lecon("Comprendre une fiche métier (texte informatif)", '''<div class="grid2"><div class="card" style="background:#fff"><b>🧭 Je m'oriente dans le texte</b><p class="sm" style="margin:1mm 0 0">Un texte informatif est organisé en <b>parties</b> avec des <b>intertitres</b> (en gras). Je ne lis pas tout : je cherche l'intertitre qui correspond à ma question.<br>« Où travaille-t-il ? » → <b>Lieux de travail</b><br>« Quelle école ? » → <b>Formation</b></p></div>
<div class="card" style="background:#fff"><b>📖 Les mots de la fiche métier</b><p class="sm" style="margin:1mm 0 0"><b>les tâches</b> : les actions du travail · <b>les conditions de travail</b> : les horaires, le lieu, la fatigue · <b>les débouchés</b> : les possibilités d'emploi · <b>un métier en pénurie</b> : on manque de travailleurs · <b>exercer</b> un métier : faire ce métier</p></div></div>''')
    e = E("Je lis la fiche métier. Dans quelle partie (① à ⑦) je trouve la réponse ? J'écris le numéro, puis la réponse.", fiche + '<p class="mt2">1. ___ Où travaille l\'aide-soignant ? ______________________________________</p><p>2. ___ Quelles sont deux qualités nécessaires ? ______________________________________</p><p>3. ___ Peut-on travailler la nuit ? ______________________________________</p>', ["lis", "ecris"], 1, "B",
          sol="1. ③ à l'hôpital, en maison de repos, à domicile — 2. ⑤ ex. : patience, douceur, écoute… — 3. ④ oui, les horaires sont variables (matin, soir, nuit, week-end)")
    b.page(f'<span class="tag-doc">🎒 FRANÇAIS DE L\'ÉCOLE</span>{l5}{e}', "Consignes & école")
    e = E("Je relis la fiche et je réponds par une phrase.", f'<p>1. Avec qui l\'aide-soignant travaille-t-il ? {blank("xl")}</p><p>2. Cite trois tâches. {blank("xl")}</p><p>3. Que veut dire « secret professionnel » ? Donne un exemple. {blank("xl")}</p><p>4. Pourquoi est-il facile de trouver du travail dans ce métier ? {blank("xl")}</p><p>5. Que faut-il faire pour exercer ce métier en Belgique ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. Sous la responsabilité d'un infirmier ou d'une infirmière, en équipe. — 2. Ex. : aider à se laver, à s'habiller, à manger ; faire le lit ; mesurer la température. — 3. Ne pas raconter aux autres ce qu'on sait sur la santé ou la vie des patients ; ex. : ne pas parler d'un patient à ses amis. — 4. C'est un métier en pénurie, très demandé. — 5. Suivre une formation (qualifiant ou promotion sociale), puis être enregistré auprès du SPF Santé publique.")
    e2 = E("Vrai ou faux ? Je recopie les mots de la fiche qui le prouvent.", vf(["L'aide-soignant travaille seul, sans équipe.", "Dans ce métier, on reste souvent debout.", "On ne peut jamais devenir infirmier ensuite."]) + lines(2), ["lis", "coche"], 2, "B",
           sol="Faux (« travail en équipe ») · Vrai (« beaucoup de temps debout ») · Faux (« Avec des études en plus, on peut devenir infirmier »)")
    e3 = E("Les mots des consignes. Je relie la consigne et ce qu'il faut faire.", relie(["Résume", "Repère", "Reformule", "Cite"], ["dis la même chose avec d'autres mots", "recopie exactement des mots du texte", "trouve et montre une information dans le texte", "dis l'essentiel en peu de mots"]), ["relie"], 1, "B",
           sol="Résume → l'essentiel en peu de mots · Repère → trouve une information · Reformule → avec d'autres mots · Cite → recopie exactement")
    b.page(f'{e}{e2}{e3}', "Consignes & école")
    e = E("Je fais la fiche métier d'un métier que j'aime, avec les 7 intertitres (je cherche avec la prof sur un site d'orientation ou j'interroge un adulte).", table(["Partie", "Mes notes"], [["① Description", ""], ["② Tâches", ""], ["③ Lieux de travail", ""], ["④ Conditions de travail", ""], ["⑤ Qualités", ""], ["⑥ Formation", ""], ["⑦ Débouchés", ""]], ["46mm", "136mm"]).replace("<td></td>", '<td style="height:17mm"></td>'), ["ecris"], 2, "C",
          sol="Fiche complète ; vérifier les informations sur la formation avec un site officiel d'orientation (SIEP, centre PMS).")
    e2 = E("Je résume ma fiche en 2 phrases pour la classe.", lines(2), ["ecris", "parle"], 2, "C", sol="Résumé court et fidèle.")
    b.page(f'{e}{e2}', "Consignes & école")

    # ---------- Documents de la vie ----------
    offre = f'''<div class="doc" style="transform:none;border:2px solid #C77D2E;background:#FFFBF4;padding:3mm 4mm;font-size:10pt;line-height:1.45"><div class="flex" style="justify-content:space-between"><div><b style="font-size:13.5pt;color:#C77D2E">🥖 Boulangerie-pâtisserie « Le Bon Grain »</b><br><span class="xs muted">Jambes (Namur) · entreprise fictive</span></div><div style="background:#C77D2E;color:#fff;border-radius:2mm;padding:1mm 3mm;font-weight:800">OFFRE DE STAGE</div></div>
<p style="margin:2mm 0 1mm"><b>Nous accueillons</b> des élèves du secondaire pour des <b>stages d'observation d'un à cinq jours</b>, de janvier à juin.</p>
<div class="grid2" style="gap:4mm"><div><p style="margin:0"><b>Le stage</b><br>• découvrir la fabrication du pain et des pâtisseries<br>• aider à la vente au magasin (avec une vendeuse)<br>• horaire : de 7 h à 13 h (pas de travail de nuit pour les mineurs)<br>• tenue : chaussures fermées, cheveux attachés ; tablier fourni</p></div>
<div><p style="margin:0"><b>Le profil</b><br>• élève de 14 ans ou plus<br>• motivé(e), ponctuel(le), propre<br>• intéressé(e) par l'alimentation<br>• connaissances de base en français</p><p style="margin:1mm 0 0"><b>Le stage n'est pas rémunéré.</b> Une convention de stage doit être signée par l'école.</p></div></div>
<p style="margin:1.5mm 0 0">📩 <b>Candidature :</b> envoyez votre CV et un court message de motivation à M. Lambotte, <b>avant le 15 février</b>, par courriel (stages@lebongrain-exemple.be) ou déposez-les au magasin.</p></div>'''
    e = E("Je lis l'offre de stage. Je réponds.", offre + f'<p class="mt2">1. Quel type de stage propose la boulangerie ? Quand ? {blank("xl")}</p><p>2. Que fait le stagiaire ? (2 choses) {blank("xl")}</p><p>3. Pourquoi le stage ne commence-t-il pas la nuit ? {blank("xl")}</p><p>4. Est-ce que le stagiaire reçoit de l\'argent ? Comment le sais-tu ? {blank("xl")}</p><p>5. Yonas a 14 ans et il est motivé. Peut-il poser sa candidature ? Que doit-il envoyer, à qui, avant quand ? {blank("xl")}</p>', ["lis", "ecris"], 2, "B",
          sol="1. Des stages d'observation d'un à cinq jours, de janvier à juin. — 2. Découvrir la fabrication du pain et des pâtisseries ; aider à la vente. — 3. Parce que le travail de nuit est interdit pour les mineurs. — 4. Non : « Le stage n'est pas rémunéré. » — 5. Oui : il doit envoyer son CV et un court message de motivation à M. Lambotte avant le 15 février.")
    b.page(f'<span class="tag-doc">📄 DOCUMENT DE LA VIE</span><h2>Une offre de stage</h2>{e}', "Document de la vie")
    e = E("Les mots de l'offre. Je relie.", relie(["rémunéré", "une candidature", "une convention de stage", "le profil", "une tenue"], ["les vêtements pour travailler", "payé", "les qualités demandées", "un contrat signé par l'école, l'entreprise et l'élève", "la demande pour obtenir un stage ou un emploi"]), ["relie"], 1, "B",
          sol="rémunéré → payé · candidature → la demande · convention → contrat signé · profil → qualités demandées · tenue → vêtements")
    mail = f'''<div class="doc" style="transform:none;border:1.5px solid #9aa1b1;font-size:10pt;background:#fff"><div style="background:#EEF1F6;padding:2mm 3mm;line-height:1.6">À : stages@lebongrain-exemple.be<br>Objet : ______________________________ &nbsp; 📎 CV_Yonas_Tesfaye.pdf</div>
<div style="padding:3mm;line-height:2">Bonjour Monsieur Lambotte,<br>Je m'appelle Yonas Tesfaye, j'ai 14 ans et je suis élève en classe DASPA à l'Athénée des Trois Ponts.<br>J'ai lu votre offre de stage et je ______________ (vouloir) faire un stage d'observation dans votre boulangerie.<br>J'aime beaucoup ______________ et je suis ______________ et ______________ .<br>______________ (pouvoir)-vous m'accueillir le ______________ ?<br>Vous trouverez mon CV en ______________ .<br>Je vous remercie d'avance et vous prie d'agréer, Monsieur, mes salutations distinguées.<br>Yonas Tesfaye</div></div>'''
    e2 = E("Je complète le courriel de candidature de Yonas.", mail, ["complete"], 2, "C",
           sol="Objet : Candidature pour un stage d'observation · voudrais · la cuisine (la pâtisserie) · motivé et ponctuel · Pourriez · [date] · pièce jointe")
    b.page(f'{e}{e2}', "Document de la vie")
    e = E("J'écoute le message de M. Lambotte sur le répondeur de l'école. Je complète la fiche.", '<div class="card" style="line-height:2"><b>📞 Message pour :</b> ______________ <br><b>De la part de :</b> ______________ <br><b>Date du stage :</b> ______________ <b>Heure d\'arrivée :</b> ______________ <br><b>À apporter :</b> ______________ <br><b>Document à renvoyer :</b> ______________ <b>avant le</b> ______________</div>', ["ecoute", "ecris"], 2, "A",
          script="« Bonjour, ici M. Lambotte, de la boulangerie Le Bon Grain. C'est un message pour Yonas Tesfaye, en classe DASPA. Yonas, nous acceptons ton stage d'observation le mercredi 10 mars. Arrive à sept heures précises, par l'entrée de derrière. Apporte des chaussures fermées ; on te donnera un tablier. Pourriez-vous, Madame, me renvoyer la convention de stage signée avant le 1er mars ? Merci et à bientôt ! »",
          sol="Yonas Tesfaye · M. Lambotte (boulangerie Le Bon Grain) · mercredi 10 mars · 7 h (entrée de derrière) · des chaussures fermées · la convention de stage signée · 1er mars")
    e2 = E("Je réponds aux questions de mes parents sur le stage de Yonas (2 phrases chacune).", '<p>1. « Combien de temps dure le stage ? Est-ce qu\'il travaille la nuit ? » ______________________________________________</p><p class="line" style="height:7mm"></p><p>2. « Est-ce qu\'il est payé ? Est-ce qu\'il y a un contrat ? » ______________________________________________</p><p class="line" style="height:7mm"></p>', ["ecris"], 2, "C",
           sol="1. Le stage dure un jour (de 7 h à 13 h). Non, il ne travaille pas la nuit : c'est interdit pour les mineurs. — 2. Non, le stage n'est pas rémunéré. Il y a une convention de stage signée par l'école.")
    e3 = E("Je compare : une offre de stage et une offre d'emploi. Qu'est-ce qui change ? (2 différences)", lines(2), ["ecris"], 3, "C", sol="Ex. : Un stage sert à apprendre, souvent sans salaire ; un emploi est payé (salaire) avec un contrat de travail. Le stage est court ; l'emploi peut durer longtemps.")
    b.page(f'{e}{e2}{e3}', "Document de la vie")

    # ---------- Sons ----------
    e = E("Les sons [ʒ] et [z]. J'écoute et je répète.", '<div class="grid2"><div class="card c"><div class="huge">[ʒ] jour</div><p>les lèvres en avant 😗, ça vibre<br>le <b>j</b>ardinier · le <b>g</b>arage · l\'in<b>g</b>énieur · la boulan<b>g</b>ère · le <b>j</b>ob</p></div><div class="card c"><div class="huge">[z] zéro</div><p>les lèvres souriantes 🙂, ça vibre<br>la coiffeu<b>s</b>e · la cui<b>s</b>ine · le ma<b>g</b>a<b>s</b>in · le <b>z</b>oo · la cai<b>ss</b>ière (attention : [s] !)</p></div></div>', ["ecoute", "repete"], 1, "A",
          script="Faire sentir : [ʒ] lèvres arrondies (comme [ʃ] mais avec la voix) ; [z] lèvres souriantes (comme [s] mais avec la voix). « g » devant e, i = [ʒ] (garage, ingénieur) ; « s » entre deux voyelles = [z] (cuisine, coiffeuse) ; « ss » = [s] (caissière). Paires : les gens / les zones ; j'ai / zéro ; le juge / la ruse.", sol="Activité orale.")
    e2 = E("J'écoute : [ʒ] ou [z] ? Je coche.", checks(8, ["[ʒ] jour", "[z] zéro"]), ["ecoute", "coche"], 2, "A", script="1. le garage — 2. la cuisine — 3. le jardinier — 4. la coiffeuse — 5. l'ingénieur — 6. le magasin — 7. le stage — 8. douze",
           sol="1. [ʒ] — 2. [z] — 3. [ʒ] — 4. [z] — 5. [ʒ] — 6. [z] — 7. [ʒ] — 8. [z]")
    e3 = E("Je lis vite et bien (virelangue).", '<div class="card big c" style="line-height:1.8">Le jeune jardinier joue au garage,<br>la coiffeuse rase douze zèbres au zoo.</div>', ["lis", "parle"], 2, "B", sol="Lecture à voix haute.")
    e4 = E("J'écris j, g, s ou z.", '<div class="card big" style="line-height:2">le ___ardinier · la cui___ine · le ma___asin (s) · ___éro · l\'in___énieur · la coiffeu___e · le sta___e · ___eune</div>', ["complete"], 1, "C", sol="jardinier · cuisine · magasin · zéro · ingénieur · coiffeuse · stage · jeune")
    b.page(f'<h2>J\'écoute bien · [ʒ] et [z]</h2>{e}{e2}{e3}{e4}', "Sons")
    e = E("L'intonation de la demande polie et de la question formelle. J'écoute et je répète : la voix monte à la fin de la question, elle reste douce.", '<div class="card big c" style="line-height:2">Pourriez-vous m\'aider ↗️ ?<br>Auriez-vous un moment ↗️ ?<br>Je voudrais un renseignement ↘️, s\'il vous plaît ↘️.<br>À quelle heure commence le stage ↘️ ?</div>', ["ecoute", "repete"], 1, "A",
          script="Faire entendre : question fermée (réponse oui / non) → la voix monte ; question avec mot interrogatif (à quelle heure, où…) → la voix peut descendre à la fin. La demande polie est dite avec un sourire dans la voix, sans brusquerie.", sol="Activité orale.")
    e2 = E("J'écoute : la personne est polie 🙂 ou impolie 😐 (ton, mots) ? Je coche.", checks(6, ["polie 🙂", "impolie 😐"]), ["ecoute", "coche"], 2, "A",
           script="1. « Pourriez-vous répéter, s'il vous plaît ? » (ton doux) — 2. « Quoi ? Répétez ! » (ton sec) — 3. « Je voudrais parler à M. Lambotte. » (ton doux) — 4. « Il est où, le chef ? » (ton sec) — 5. « Excusez-moi, auriez-vous un stylo ? » — 6. « Donnez-moi un stylo. » (ton sec)",
           sol="1. polie — 2. impolie — 3. polie — 4. impolie — 5. polie — 6. impolie")
    e3 = E("En duo : au téléphone. A est élève et demande un stage (avec 3 phrases au conditionnel). B est le patron et répond. On échange.", '<div class="card sm" style="background:#EEF1F6">A : Bonjour Madame / Monsieur, je m\'appelle… Je voudrais… Pourriez-vous… ? Serait-il possible de… ? · B : Oui, bien sûr. / Désolé(e), ce n\'est pas possible… · A : Je vous remercie. Au revoir, Madame / Monsieur.</div>' + lines(2), ["parle", "duo"], 2, "A", sol="Activité orale : conditionnel, intonation, formules de politesse.")
    e4 = E("Je transforme en demande polie, puis je la dis à mon voisin avec un sourire dans la voix.", '<p>1. Donnez-moi l\'adresse. → ______________________________ ?</p><p>2. Je veux parler à la responsable. → ______________________________ .</p><p>3. Vous avez un formulaire ? → ______________________________ ?</p>', ["ecris", "parle"], 2, "C",
           sol="1. Pourriez-vous me donner l'adresse, s'il vous plaît ? — 2. Je voudrais parler à la responsable, s'il vous plaît. — 3. Auriez-vous un formulaire ?")
    b.page(f'<h2>J\'écoute bien · l\'intonation polie</h2>{e}{e2}{e3}{e4}', "Sons")

    # ---------- Révision spirale ----------
    e = E("🔁 Module 10 · La cause et la conséquence.", '<p>Je voudrais être infirmière ______ j\'aime aider les gens. Le stage commence à 7 h, ______ je me lève tôt. ______ M. Diallo, j\'ai écrit un bon CV.</p>', ["complete"], 1, "C", sol="parce que (car) · donc · Grâce à")
    e2 = E("🔁 Module 9 · Le conseil.", '<p>Pour un entretien, tu (devoir) ______________ arriver à l\'heure. Il ______ mieux préparer ses questions.</p>', ["complete"], 1, "C", sol="devrais · vaut")
    e3 = E("🔁 Module 8 · Le courriel formel. J'écris la formule d'appel et la formule finale d'un courriel à un patron.", lines(2), ["ecris"], 1, "C", sol="Bonjour Monsieur / Madame, … Je vous remercie d'avance et vous prie d'agréer mes salutations distinguées.")
    e4 = E("🔁 Module 8 · qui, que, où.", '<p>C\'est un métier ______ me plaît. Le garage ______ je fais mon stage est à Jambes. L\'entreprise ______ j\'ai choisie est petite.</p>', ["complete"], 1, "C", sol="qui · où · que")
    e5 = E("🔁 Module 7 · Si + présent, futur.", '<p>Si je (réussir) ______________ mes études, je (devenir) ______________ électricienne. Si tu (être) ______________ ponctuel, le patron (être) ______________ content.</p>', ["complete"], 2, "C", sol="réussis · deviendrai · es · sera")
    e6 = E("🔁 Module 6 · Le comparatif et le superlatif.", '<p>Le métier de maçon est ______ physique ______ le métier de secrétaire. Pour moi, la cuisine est le métier le ______ intéressant.</p>', ["complete"], 1, "C", sol="plus · que · plus")
    e7 = E("🔁 Module 3 · Imparfait et passé composé. « Quand j'étais petit(e), je voulais être… Un jour, … » (2 phrases)", lines(2), ["ecris"], 3, "C", sol="Ex. : Quand j'étais petite, je voulais être pilote. Un jour, j'ai visité un aéroport et j'ai vu les avions de près.")
    b.page(f'<h2>🔁 Je révise les modules 1 à 10</h2>{e}{e2}{e3}{e4}{e5}{e6}{e7}', "Je révise")

    # ---------- Ateliers ----------
    e = E("Quel est mon métier ? (jeu des 20 questions). Un élève choisit secrètement un métier. Les autres posent des questions formelles (réponse : oui / non). On devine en moins de 20 questions !", '<div class="card sm" style="background:' + TINT + '">Travaillez-vous dehors ? · Utilisez-vous des outils ? · Travaillez-vous avec des enfants ? · Faut-il faire des études longues ? · Portez-vous un uniforme ? · Travaillez-vous la nuit ? · Êtes-vous en contact avec des clients ?</div>' +
          '<p class="sm mt2">Les questions de mon équipe :</p>' + lines(6), ["parle", "groupe", "ecris"], 2, "A",
          sol="Évaluer : inversion correcte, vouvoiement, variété des questions.")
    e2 = E("Je note les métiers devinés par la classe et la question qui a le plus aidé.", lines(2), ["ecoute", "ecris"], 1, "A", sol="Réponse personnelle.")
    e3 = E("Je m'évalue.", table(["", "😀", "🙂", "😕"], [[x, '<span class="chk"></span>', '<span class="chk"></span>', '<span class="chk"></span>'] for x in ["J'ai posé des questions avec l'inversion.", "J'ai vouvoyé la personne qui répondait.", "J'ai écouté les questions des autres pour ne pas répéter."]], ["128mm", "18mm", "18mm", "18mm"]), ["coche"], 1, "A", sol="Auto-évaluation.")
    b.page(f'{atl_head("A", "Atelier · Quel est mon métier ?")}{e}{e2}{e3}', "Atelier")
    ann = [("A", "🧒 Crèche « Les Petits Pas » (fictive) cherche stagiaire d'observation. Aimer les enfants, être patient(e) et doux(ce). Mercredi après-midi."), ("B", "🔧 Garage Meuse Auto (fictif) accueille un(e) stagiaire passionné(e) de voitures. Minutieux(se), pas peur de se salir. Tenue de travail fournie."),
           ("C", "💻 Bureau d'informatique (fictif) : découvrir la réparation d'ordinateurs. Curieux(se), aimer les écrans et les problèmes à résoudre."), ("D", "🛒 Supermarché de quartier (fictif) : découvrir la mise en rayon et la caisse. Sociable, aimer le contact avec les clients.")]
    pers = ["Fatou adore les enfants et elle est très calme.", "Bilal aime parler avec tout le monde et rendre service.", "Mateo démonte et remonte son vélo tous les week-ends.", "Daria passe des heures à chercher pourquoi son ordinateur est lent."]
    e = E("Je lis les annonces de stages et je trouve un stage pour chaque élève. J'écris la lettre et je justifie avec un mot de l'annonce.", '<div class="grid2" style="gap:2mm">' + "".join(f'<div class="card sm" style="background:#fff"><b>{k}</b> · {t}</div>' for k, t in ann) + '</div>' +
          table(["Élève", "Annonce", "Parce que… (mot de l'annonce)"], [[p, "", ""] for p in pers], ["80mm", "22mm", "80mm"]).replace("<td></td>", '<td style="height:9mm"></td>'), ["lis", "ecris"], 2, "B",
          sol="Fatou → A (aimer les enfants, patiente, douce) · Bilal → D (sociable, contact avec les clients) · Mateo → B (passionné de voitures, minutieux) · Daria → C (curieuse, problèmes à résoudre)")
    e2 = E("Et moi ? Quelle annonce je choisis ? Pourquoi ? (2 phrases avec mes qualités)", lines(2), ["ecris"], 1, "C", sol="Choix justifié avec des qualités.")
    e3 = E("J'écris une petite annonce de stage pour un lieu de mon quartier (lieu, tâches, profil, jour), sur le modèle.", lines(3), ["ecris"], 3, "C", sol="Annonce avec lieu, tâches, qualités demandées, horaire.")
    b.page(f'{atl_head("B", "Atelier · Le stage idéal")}{e}{e2}{e3}', "Atelier")
    e = E("J'écris un courriel de candidature pour le stage de mon choix (atelier B ou boulangerie Le Bon Grain) : objet, formule d'appel, présentation, demande polie au conditionnel, qualités, pièce jointe, formule finale, signature.", '<div class="doc" style="transform:none;border:1.5px solid #9aa1b1;background:#fff"><div style="background:#EEF1F6;padding:2mm 3mm;line-height:2">À : ………………………………………………<br>Objet : …………………………………………… &nbsp; 📎 ……………</div><div style="padding:3mm">' + lines(11) + '</div></div>', ["ecris"], 2, "C",
          sol="Courriel complet et formel (vouvoiement, conditionnel de politesse, qualités justifiées).")
    e2 = E("Je relis avec la check-list : objet clair ? vouvoiement ? 2 verbes au conditionnel ? pièce jointe ? pas d'émoji ? Je coche et je corrige.", '', ["lis"], 1, "C", sol="Relecture.")
    b.page(f'{atl_head("C", "Atelier · Ma candidature")}{e}{e2}', "Atelier")
    fam = [("🧑‍🍳", "cuisinier", "🍽️ restaurant", "🔪 couteau", "⚡ rapide"), ("🔧", "mécanicien", "🚗 garage", "🔩 clé", "🔍 minutieux"), ("🧑‍⚕️", "infirmière", "🏥 hôpital", "💉 seringue", "🧘 patiente"), ("💇", "coiffeuse", "💈 salon", "✂️ ciseaux", "🎨 créative"),
           ("🧑‍🌾", "agriculteur", "🌾 ferme", "🚜 tracteur", "💪 résistant"), ("🧑‍🏫", "professeure", "🏫 école", "📚 livres", "🤝 patiente, sociable")]
    grid = '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:1.5mm">' + "".join(f'<div class="card c" style="min-height:31mm;padding:1.5mm;background:{TINT if r % 2 else "#fff"};display:flex;flex-direction:column;justify-content:center"><span class="xs">{x}</span></div>' for r, f in enumerate(fam) for x in (f"<span style='font-size:20pt'>{f[0]}</span><br><b>{f[1]}</b>", f"<span style='font-size:16pt'>{f[2][:2]}</span><br>{f[2][2:]}", f"<span style='font-size:16pt'>{f[3][:2]}</span><br>{f[3][2:]}", f"<span style='font-size:16pt'>{f[4][:2]}</span><br>{f[4][2:]}")) + '</div>'
    e = E("Le jeu des 6 familles de métiers (3 à 5 joueurs). On découpe les 24 cartes. Pour gagner une carte, je demande poliment : « Pourriez-vous me donner l'outil du cuisinier, s'il vous plaît ? » La famille complète = métier + lieu + outil + qualité.", grid, ["joue", "groupe"], 2, "D",
          sol="Chaque famille : métier, lieu, outil, qualité. Demande obligatoire au conditionnel, sinon on passe son tour.")
    b.page(f'{atl_head("D", "Atelier · Les familles de métiers")}{e}', "Atelier")

    # ---------- ★ Coup de pouce ----------
    e = E("Je relie le métier et l'image.", relie(["le cuisinier", "l'infirmière", "le mécanicien", "la coiffeuse", "le boulanger"], ["🥖", "💇", "🔧", "🧑‍⚕️", "🧑‍🍳"]), ["relie"], 1, "B", alpha=True, sol="cuisinier → 🧑‍🍳 · infirmière → 🧑‍⚕️ · mécanicien → 🔧 · coiffeuse → 💇 · boulanger → 🥖")
    e2 = E("Où travaille-t-il ? J'entoure.", '<div class="card big" style="line-height:2">Le mécanicien travaille dans un (garage / hôpital).<br>L\'infirmière travaille dans un (magasin / hôpital).<br>Le cuisinier travaille dans un (restaurant / garage).</div>', ["entoure"], 1, "B", alpha=True, sol="garage · hôpital · restaurant")
    e3 = E("Je complète : Je suis ______ (mon métier rêvé). Je travaille dans ______ .", '<div class="card" style="background:#F2FBF7"><p class="big" style="line-height:2.2">Plus tard, je voudrais être ______________ .<br>Je travaillerai dans ______________ .</p></div>', ["ecris"], 1, "C", alpha=True, sol="Phrases sur le modèle.")
    e4 = E("J'écris le féminin.", '<div class="card big" style="line-height:2">un vendeur → une ______________ · un cuisinier → une ______________</div>', ["ecris"], 1, "C", alpha=True, sol="vendeuse · cuisinière")
    b.page(CP.format(t="Les métiers · les lieux") + e + e2 + e3 + e4, "★ Coup de pouce")
    e = E("Poli ou pas poli ? Je coche.", vf(["Je veux un stage !", "Je voudrais un stage, s'il vous plaît.", "Pourriez-vous m'aider ?", "Aide-moi !"]).replace("Vrai", "🙂").replace("Faux", "😐"), ["coche"], 1, "B", alpha=True, sol="😐 · 🙂 · 🙂 · 😐")
    e2 = E("Je complète avec : voudrais · pourriez · aimerais.", '<div class="card" style="background:#F2FBF7"><p class="big" style="line-height:2.2">Je ______________ faire un stage.<br>J\'______________ observer une infirmière.<br>______________ -vous m\'aider ?</p></div>', ["complete"], 1, "C", alpha=True, sol="voudrais · aimerais · Pourriez")
    e3 = E("Je relie la qualité et l'image.", relie(["ponctuel", "sociable", "patient"], ["🤝", "⏰", "🧘"]), ["relie"], 1, "B", alpha=True, sol="ponctuel → ⏰ · sociable → 🤝 · patient → 🧘")
    e4 = E("Je dis mon métier avec le modèle (sans article !).", '<div class="card" style="background:#F2FBF7"><p class="big" style="line-height:2.1">Ma mère est ______________ . · Mon oncle est ______________ .<br>Plus tard, je voudrais être ______________ .</p></div>', ["ecris"], 1, "C", alpha=True, sol="Phrases sur le modèle, sans article.")
    b.page(CP.format(t="Demander poliment · les qualités") + e + e2 + e3 + e4, "★ Coup de pouce")
    e = E("Je complète mon petit CV.", '<div class="card" style="background:#F2FBF7;line-height:2.2"><p class="big" style="margin:0">Nom : ______________ Prénom : ______________<br>Âge : ______ ans · École : ______________<br>Langues : ______________________________<br>Qualités : ______________ · ______________<br>Loisirs : ______________________________</p></div>', ["ecris"], 1, "C", alpha=True, sol="CV personnel.")
    e2 = E("Je remets la conversation dans l'ordre (1 à 4).", '<div class="card big" style="line-height:2">___ Je voudrais faire un stage, s\'il vous plaît.<br>___ Merci beaucoup ! Au revoir, Monsieur.<br>___ Bonjour Monsieur.<br>___ Oui, venez lundi à 8 h.</div>', ["numerote"], 1, "B", alpha=True, sol="2 · 4 · 1 · 3")
    e3 = E("Je pose la question au patron avec le modèle « Quelle est… ? / Quels sont… ? ».", '<div class="card big" style="line-height:2">Quels sont les ______________ ? (horaires) · Quelle est l\'______________ ? (adresse)</div>', ["complete"], 1, "C", alpha=True, sol="horaires · adresse")
    b.page(CP.format(t="Mon CV · l'entretien") + e + e2 + e3, "★ Coup de pouce")

    # ---------- Tâche finale ----------
    grid_q = table(["Question du recruteur", "Ce que je peux répondre"], [["Pouvez-vous vous présenter ?", "Je m'appelle… J'ai… ans. Je suis en classe… Je parle… langues."], ["Pourquoi voulez-vous faire ce stage ?", "Parce que je voudrais découvrir le métier de… / J'aimerais devenir…"], ["Quelles sont vos qualités ?", "Je suis… Par exemple, …"], ["Avez-vous déjà une expérience ?", "Oui, j'ai déjà… / Non, mais j'ai aidé… / j'ai fait…"], ["Avez-vous des questions ?", "Oui : Quels sont les horaires ? Comment dois-je m'habiller ? Que ferai-je pendant la journée ?"]], ["70mm", "112mm"])
