    e = E("Je prépare mes réponses à l'entretien (une ou deux phrases par question).", table(["Question", "Ma réponse"], [["Pouvez-vous vous présenter ?", ""], ["Pourquoi voulez-vous faire ce stage ?", ""], ["Quelles sont vos qualités ? (avec un exemple)", ""], ["Avez-vous déjà une expérience ?", ""], ["Mes 2 questions pour le recruteur (formelles)", ""]], ["62mm", "120mm"]).replace("<td></td>", '<td style="height:18mm"></td>'), ["ecris"], 2, "C", sol="Réponses complètes, conditionnel, questions formelles.")
